import{_ as p,r as n,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"用户和权限 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"用户和权限","slug":"用户和权限","link":"#用户和权限","children":[]},{"level":2,"title":"后端用户助手","slug":"后端用户助手","link":"#后端用户助手","children":[]},{"level":2,"title":"注册权限","slug":"注册权限","link":"#注册权限","children":[]},{"level":2,"title":"限制对后端页面的访问","slug":"限制对后端页面的访问","link":"#限制对后端页面的访问","children":[]},{"level":2,"title":"限制对功能的访问","slug":"限制对功能的访问","link":"#限制对功能的访问","children":[]}],"relativePath":"2.x/zh-cn/backend/users.md","filePath":"2.x/zh-cn/backend/users.md"}'),i={name:"2.x/zh-cn/backend/users.md"};function u(k,s,d,g,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"用户和权限",-1)),a(e),s[1]||(s[1]=r(`<p>后端的用户管理包括角色、组、权限、密码重置和登录限制等功能。插件还可以注册权限来控制对后端功能的访问。</p><p><a id="oc-users-and-permissions"></a></p><h2 id="用户和权限"><a href="#用户和权限" class="header-anchor">#</a> 用户和权限</h2><p>对October CMS实例的所有部分的访问由权限系统控制。在最低级别，有超级用户(<code>is_superuser</code> 标志设置为 true 的用户)、管理员(用户)和权限。 <code>\\Backend\\Models\\User</code> 模型是保存有关用户的所有重要信息的容器。</p><p>超级用户可以访问系统中的所有内容，并且只能由他们自己或其他超级用户管理；即使管理员拥有<code>backend.manage_users</code>权限，常规管理员也无法看到或编辑它们。</p><blockquote><p><strong>注意</strong>：任何拥有 <code>manage_users</code> 权限的用户都可以管理角色的分配，但只能分配给其他用户(不能分配给自己)，并且角色只能由超级用户创建或修改。</p></blockquote><p>权限是 <code>author.plugin.permission_name</code> 形式的字符串key，通过在编辑管理员页面上直接分配或通过用户角色继承授予用户。</p><p>检查用户是否具有特定权限时，该用户角色的权限设置将被继承，然后被直接应用于该用户的任何权限覆盖。例如，如果用户 <strong>Bob</strong> 具有角色 <strong>Genius</strong>，并且角色 <strong>Genius</strong> 具有 <code>eat_cake</code> 权限，但 <strong>Bob</strong> 具有专门设置为拒绝的 <code>eat_cake</code> 权限，则 * <em>Bob</em>* 不会去 <code>eat_cake</code>。但是，如果 <strong>Bob</strong> 具有直接分配给他的 <code>eat_vegetables</code> 权限，但 <strong>Genius</strong> 角色没有，那么 <strong>Bob</strong> 仍然可以访问 <code>eat_vegetables</code>。</p><p>角色 (<code>\\Backend\\Models\\UserRole</code>) 是权限分组，具有用于识别角色的名称和描述。管理员一次只能分配一个角色。一个角色可以分配给多个管理员。October默认附带两个系统角色，<code>developer</code>和<code>publisher</code>。可以创建具有自己权限组合的任意数量的自定义角色并将其应用于用户。</p><blockquote><p><strong>注意</strong>：系统角色(<code>developer</code>、<code>publisher</code> 以及 <code>is_system</code> 设置为 <code>true</code> 的任何角色)不能通过后端更改其权限。假定他们有权访问所有权限，除非给定权限指定了一个或多个特定角色，它使用权限定义中的<code>roles</code>数组键(在这种情况下，只有指定的系统角色有权访问它)。</p></blockquote><p>组(<code>\\Backend\\Models\\UserGroup</code>)是用于对管理员进行分组的组织工具，可以将它们视为<code>用户类别</code>。它们与权限无关，仅用于组织目的。例如，如果您想向 <code>总公司职员</code> 组中的所有用户发送电子邮件，您只需执行 <code>Mail::sendTo(UserGroup::where(&#39;code&#39;, &#39;head-office-staff&#39; )-&gt;get()-&gt;users, &#39;author.plugin::mail.important_notification&#39;, $data);</code></p><h2 id="后端用户助手"><a href="#后端用户助手" class="header-anchor">#</a> 后端用户助手</h2><p>全局 <code>BackendAuth</code> 门面可用于管理管理用户，它主要继承 <code>October\\Rain\\Auth\\Manager</code> 类。要注册新的管理员用户帐户，请使用 <code>BackendAuth::register</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Some&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;last_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;some@website.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;changeme&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>BackendAuth::check</code> 方法是检查用户是否已登录的快速方法。要返回已登录的用户模型，请改用 <code>BackendAuth::getUser</code>。 此外，活动用户将在任何 <a href="./../backend/controllers-ajax.html">后端控制器</a> 中作为 <code>$this-&gt;user</code> 使用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 如果已登录，则返回 true。</span>
<span class="token variable">$loggedIn</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 返回登录用户</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 从控制器返回登录用户</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">user</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>BackendAuth::findUserByLogin</code> 方法通过登录名查找用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">findUserByLogin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;someuser&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以通过使用 <code>BackendAuth::authenticate</code> 提供他们的登录名和密码来验证用户。 您还可以通过将 <code>Backend\\Models\\User</code> 模型与 <code>BackendAuth::login</code> 一起传递来以用户身份进行身份验证。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 通过凭据对用户进行身份验证</span>
<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">authenticate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 以特定用户身份登录</span>
<span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">login</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="注册权限"><a href="#注册权限" class="header-anchor">#</a> 注册权限</h2><p>插件可以通过覆盖<a href="./../plugin/registration.html#oc-registration-file">插件注册类</a>中的<code>registerPermissions</code>方法来注册后端用户权限。 权限被定义为一个数组，其中键对应于权限键，值对应于权限描述。 权限密钥由作者姓名、插件名称和功能名称组成。 这是一个示例代码：</p><div class="language- extra-class"><pre class="language-text"><code>acme.blog.access_categories
</code></pre></div><p>下一个示例显示如何注册后端权限项。 权限是使用权限密钥和描述定义的。 在后端权限管理用户界面中，权限显示为复选框列表。 后端控制器可以使用插件定义的权限来限制用户访问 <a href="#oc-restricting-access-to-backend-pages">页面</a> 或 <a href="#oc-restricting-access-to-features">功能</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;管理博客文章&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以将 <code>roles</code> 选项指定为一个数组，其中每个值作为角色 API 代码。 当使用此代码创建角色时，它会成为系统角色，该角色始终将此权限授予具有该角色的用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;管理博客类别&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;developer&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-restricting-access-to-backend-pages"></a></p><h2 id="限制对后端页面的访问"><a href="#限制对后端页面的访问" class="header-anchor">#</a> 限制对后端页面的访问</h2><p>在后端控制器类中，您可以指定访问控制器提供的页面需要哪些权限。 它是通过 <code>$requiredPermissions</code> 控制器的属性完成的。 此属性应包含一组权限键。 如果用户权限与列表中的任何权限匹配，则框架将让用户查看控制器页面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>BackendController</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name">BackendController</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</span></code></pre></div><p>您还可以使用 <strong>asterisk</strong> 符号表示&quot;所有权限&quot;条件。 在下一个示例中，所有具有以&quot;acme.blog.&quot;字符串开头的权限的用户都可以访问控制器页面：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-restricting-access-to-features"></a></p><h2 id="限制对功能的访问"><a href="#限制对功能的访问" class="header-anchor">#</a> 限制对功能的访问</h2><p>后端用户模型具有允许确定用户是否具有特定权限的方法。 您可以使用此功能来限制后端用户界面的功能。 后端用户支持的权限方式有<code>hasAccess</code>和<code>hasPermission</code>。 这两种方法都采用两个参数：权限键字符串(或键字符串数组)和一个可选参数，该参数指示与第一个参数一起列出的所有权限都是必需的。</p><p>如果用户是超级用户(<code>is_superuser</code> 设置为 <code>true</code>)，<code>hasAccess</code> 方法会为任何权限返回 <strong>true</strong>。 <code>hasPermission</code> 方法更严格，仅当用户在其帐户中或通过其角色实际上具有指定的权限时才返回 true。 通常，<code>hasAccess</code> 是首选方法，因为它尊重超级用户的绝对权力。 以下示例显示了如何使用控制器代码中的方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">user</span><span class="token operator">-&gt;</span><span class="token function">hasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">user</span><span class="token operator">-&gt;</span><span class="token function">hasPermission</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以使用后端视图中的方法来隐藏用户界面元素。 下一个示例演示如何隐藏编辑类别 <a href="./表单.html">后端表单</a>上的按钮：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">user</span><span class="token operator">-&gt;</span><span class="token function">hasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.delete_categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger pull-right<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-load-indicator</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>删除类别...<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>你真的要删除这个类别吗?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div>`,40))])}const f=p(i,[["render",u]]);export{b as __pageData,f as default};
